(()=>{const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];q('.portal-page')?.classList.add('wrap');function scrollToId(id){const el=document.getElementById(id);if(!el||el.hidden)return false;el.scrollIntoView({behavior:'smooth',block:'start'});qa('.nav-item').forEach(btn=>btn.classList.toggle('active',btn.dataset.scroll===id));return true;}qa('[data-scroll]').forEach(btn=>btn.addEventListener('click',()=>scrollToId(btn.dataset.scroll)));qa('[data-focus-search]').forEach(btn=>btn.addEventListener('click',()=>q('#hero-search-input')?.focus()));const hero=q('#hero-search-input'),request=q('#request-search'),go=q('#hero-search-button');function runHeroSearch(){if(!hero||!request)return;request.value=hero.value;request.dispatchEvent(new Event('input',{bubbles:true}));scrollToId('requests-section');request.focus();}go?.addEventListener('click',runHeroSearch);hero?.addEventListener('keydown',event=>{if(event.key==='Enter')runHeroSearch();});const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting&&e.intersectionRatio>.25).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!visible)return;qa('.nav-item').forEach(btn=>btn.classList.toggle('active',btn.dataset.scroll===visible.target.id));},{threshold:[.25,.5,.75]});['home','requests-section','quick-actions-section','assets-section','approvals-section','reports-section'].forEach(id=>{const el=document.getElementById(id);if(el)observer.observe(el);});})();